// NativeDecision is the API-neutral routing data needed by the native runner.
type NativeDecision struct {
	Harness    string
	Provider   string
	Model      string
	Candidates []NativeRouteCandidate
}

// NativeRouteCandidate is the API-neutral subset of root RouteCandidate used
// by the native failover provider.
type NativeRouteCandidate struct {
	Provider string
	Endpoint string
	Model    string
	Eligible bool
}

// NativeRequest is the API-neutral request data needed by the native runner.
type NativeRequest struct {
	Prompt                    string
	SystemPrompt              string
	Model                     string
	Provider                  string
	Harness                   string
	WorkDir                   string
	Temperature               *float32
	TopP                      *float64
	TopK                      *int
	MinP                      *float64
	RepetitionPenalty         *float64
	Seed                      *int64
	SamplingSource            string
	Reasoning                 agentcore.Reasoning
	NoStream                  bool
	Permissions               string
	Tools                     []agentcore.Tool
	ToolPreset                string
	PlanningMode              bool
	MaxIterations             int
	MaxTokens                 int
	ReasoningByteLimit        int
	ProviderTimeout           time.Duration
	Timeout                   time.Duration
	CachePolicy               string
	StallMaxReadOnlyIteration *int
	Metadata                  map[string]string
	Decision                  NativeDecision
	Started                   time.Time
	SessionID                 string
}

// NativeProviderRequest is the narrow provider-selection request that crosses
// from the internal runner back into root-owned provider configuration.
type NativeProviderRequest struct {
	Provider string
	Harness  string
	Model    string
}

// NativeProviderResolution is the API-neutral result of root-owned provider
// construction.
type NativeProviderResolution struct {
	Provider agentcore.Provider
	Name     string
	Model    string
}

// NativeCallbacks are root-owned service seams used by the internal runner
// without importing root public contract types.
type NativeCallbacks struct {
	ResolveProvider            func(NativeProviderRequest) NativeProviderResolution
	ProviderNotConfiguredError func(NativeProviderRequest, NativeDecision) string
	Compactor                  func(model string) agentcore.Compactor
	ObserveAgentEvent          func(agentcore.Event)
	EmitEvent                  func(harnesses.EventType, any)
	BeforeFinal                func(harnesses.FinalData)
	Finalize                   func(harnesses.FinalData)
	ToolWiringHook             func(harness string, toolNames []string)
	PromptAssertionHook        func(systemPrompt, prompt string, contextFiles []string)
	CompactionAssertionHook    func(messagesBefore, messagesAfter, tokensFreed int)
	ObserveTokenUsage          func(provider string, tokens int, at time.Time)
}

// RunNative drives the in-process agent loop without depending on root public
// service types.
func RunNative(ctx context.Context, req NativeRequest, cb NativeCallbacks) {
	provider := nativeExecutionProvider(req, cb.ResolveProvider)
	actualHarness := req.Decision.Harness
	if actualHarness == "" {
		actualHarness = "agent"
	}
	resolvedProvider := resolveProvider(cb.ResolveProvider, nativeProviderRequest(req, req.Decision))
	actualProvider := resolvedProvider.Name
	if actualProvider == "" {
		actualProvider = req.Decision.Provider
	}
	actualModel := req.Decision.Model
	if actualModel == "" {
		actualModel = resolvedProvider.Model
	}
	if provider == nil {
		finalize(cb, harnesses.FinalData{
			Status:     "failed",
			Error:      providerNotConfiguredError(cb.ProviderNotConfiguredError, req, req.Decision),
			DurationMS: time.Since(req.Started).Milliseconds(),
			RoutingActual: &harnesses.RoutingActual{
				Harness:  actualHarness,
				Provider: actualProvider,
				Model:    actualModel,
			},
		})
		return
	}
	permission, permissionErr := nativePermissionMode(req.Permissions)
	if permissionErr != nil {
		finalize(cb, harnesses.FinalData{
			Status:     "failed",
			Error:      permissionErr.Error(),
			DurationMS: time.Since(req.Started).Milliseconds(),
			RoutingActual: &harnesses.RoutingActual{
				Harness:  actualHarness,
				Provider: actualProvider,
				Model:    actualModel,
			},
		})
		return
	}

	if req.ProviderTimeout > 0 {
		provider = wrapProviderRequestTimeout(provider, req.ProviderTimeout)
	}

	policyMax := defaultStallReadOnlyIterations
	if req.StallMaxReadOnlyIteration != nil {
		policyMax = *req.StallMaxReadOnlyIteration
	}
	maxIter := req.MaxIterations
	if maxIter <= 0 {
		maxIter = defaultMaxIterations
	}

	var (
		readOnlyStreak atomic.Int64
		stalled        atomic.Bool
		stallReason    atomic.Value
		stallCount     atomic.Int64
	)
	cancelCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	loopCB := func(ev agentcore.Event) {
		if cb.ObserveAgentEvent != nil {
			cb.ObserveAgentEvent(ev)
		}
		switch ev.Type {
		case agentcore.EventToolCall:
			var payload nativeToolCallPayload
			_ = json.Unmarshal(ev.Data, &payload)
			if !toolLikelyMakesProgress(payload.Tool, payload) {
				if v := readOnlyStreak.Add(1); policyMax > 0 && int(v) >= policyMax {
					if stalled.CompareAndSwap(false, true) {
						stallReason.Store("no_progress_tools_exceeded")
						stallCount.Store(v)
						cancel()
					}
				}
			} else {
				readOnlyStreak.Store(0)
			}
		case agentcore.EventCompactionEnd:
			if cb.CompactionAssertionHook != nil {
				var payload nativeCompactionPayload
				_ = json.Unmarshal(ev.Data, &payload)
				cb.CompactionAssertionHook(payload.MessagesBefore, payload.MessagesAfter, payload.TokensBefore-payload.TokensAfter)
			}
		}
	}

	tools := filterNativeToolsForPermission(req.Tools, permission)
	if cb.ToolWiringHook != nil {
		cb.ToolWiringHook(req.Decision.Harness, ToolNames(tools))
	}
	if cb.PromptAssertionHook != nil {
		cb.PromptAssertionHook(req.SystemPrompt, req.Prompt, nil)
	}

	var compactor agentcore.Compactor
	if cb.Compactor != nil {
		compactor = cb.Compactor(actualModel)
	}
	var temperature *float64
	if req.Temperature != nil {
		t := float64(*req.Temperature)
		temperature = &t
	}
	var seed int64
	if req.Seed != nil {
		seed = *req.Seed
	}
	loopReq := agentcore.Request{
		Prompt:             req.Prompt,
		SystemPrompt:       req.SystemPrompt,
		Provider:           provider,
		Tools:              tools,
		WorkDir:            req.WorkDir,
		Callback:           loopCB,
		Metadata:           req.Metadata,
		MaxIterations:      maxIter,
		ResolvedModel:      actualModel,
		SelectedProvider:   actualProvider,
		Temperature:        temperature,
		TopP:               req.TopP,
		TopK:               req.TopK,
		MinP:               req.MinP,
		RepetitionPenalty:  req.RepetitionPenalty,
		Seed:               seed,
		SamplingSource:     req.SamplingSource,
		Reasoning:          req.Reasoning,
		NoStream:           req.NoStream,
		MaxTokens:          req.MaxTokens,
		ReasoningByteLimit: req.ReasoningByteLimit,
		Compactor:          compactor,
		CachePolicy:        req.CachePolicy,
		PlanningMode:       req.PlanningMode || req.ToolPreset == "benchmark",
	}
	result, runErr := agentcore.Run(cancelCtx, loopReq)

	if err != nil {
		return ProviderConfig{}, "", fmt.Errorf("config: endpoint %d: %w", ordinal, err)
	}
	name := strings.TrimSpace(endpoint.Name)
	if name == "" {
		name = generatedEndpointProviderName(endpoint, providerType, baseURL, ordinal)
	}
	return ProviderConfig{
		Type:    providerType,
		BaseURL: baseURL,
		Endpoints: []ProviderEndpoint{{
			Name:    "default",
			BaseURL: baseURL,
		}},
		APIKey:    endpoint.APIKey,
		Headers:   endpoint.Headers,
		Reasoning: endpoint.Reasoning,
	}, name, nil
}

func endpointBaseURL(endpoint EndpointConfig, providerType string) (string, error) {
	if baseURL := strings.TrimSpace(endpoint.BaseURL); baseURL != "" {
		return baseURL, nil
	}
	if providerType == "openrouter" {
		return openrouter.DefaultBaseURL, nil
	}
	host := strings.TrimSpace(endpoint.Host)
	if host == "" {
		return "", fmt.Errorf("host or base_url is required")
	}
	port := endpoint.Port
	if port == 0 {
		port = defaultEndpointPort(providerType)
	}
	if port == 0 {
		return "", fmt.Errorf("port is required for provider type %q", providerType)
	}
	if strings.HasPrefix(host, "http://") || strings.HasPrefix(host, "https://") {
		return strings.TrimRight(fmt.Sprintf("%s:%d", strings.TrimRight(host, "/"), port), "/") + "/v1", nil
	}
	return fmt.Sprintf("http://%s:%d/v1", host, port), nil
}

func defaultEndpointPort(providerType string) int {
	switch providerType {
	case "lmstudio":
		return 1234
	case "llama-server":
		return 8080
	case "omlx":
		return 1235
	case "lucebox":
		return 1236
	case "vllm":
		return 8000
	case "ollama":
		return 11434
	default:
		return 0
	}
}

func generatedEndpointProviderName(endpoint EndpointConfig, providerType, baseURL string, ordinal int) string {
	host := strings.TrimSpace(endpoint.Host)
	if host == "" {
		host = strings.TrimSpace(baseURL)
	}
	host = strings.NewReplacer("http://", "", "https://", "", "/v1", "", "/", "-", ":", "-").Replace(host)
	if host == "" {
		return fmt.Sprintf("%s-%d", providerType, ordinal)
	}
	if endpoint.Port > 0 {
		return fmt.Sprintf("%s-%s-%d", providerType, host, endpoint.Port)
	}
	return fmt.Sprintf("%s-%s", providerType, host)
}

func uniqueEndpointProviderName(name string, used map[string]bool) string {
	if !used[name] {
		return name
	}
	for i := 2; ; i++ {
		candidate := fmt.Sprintf("%s-%d", name, i)
		if !used[candidate] {
			return candidate
		}
	}
}

func normalizeProviderConfig(pc ProviderConfig) ProviderConfig {
	pc.Type = strings.ToLower(strings.TrimSpace(pc.Type))
	pc.BaseURL = strings.TrimSpace(pc.BaseURL)
	for i := range pc.Endpoints {
		pc.Endpoints[i].Name = strings.TrimSpace(pc.Endpoints[i].Name)
		pc.Endpoints[i].BaseURL = strings.TrimSpace(pc.Endpoints[i].BaseURL)
	}
	if pc.BaseURL == "" && len(pc.Endpoints) > 0 {
		pc.BaseURL = pc.Endpoints[0].BaseURL
	}
	if pc.Type == "" {
		pc.Type = inferProviderTypeFromBaseURL(pc.BaseURL)
	}
	switch pc.Type {
	case "openrouter":
		if pc.BaseURL == "" {
			pc.BaseURL = openrouter.DefaultBaseURL
		}
	case "openai":
		if pc.BaseURL == "" {
			pc.BaseURL = "https://api.openai.com/v1"
		}
	case "lmstudio":
		if pc.BaseURL == "" {
			pc.BaseURL = lmstudio.DefaultBaseURL
		}
	case "llama-server":
		if pc.BaseURL == "" {
			pc.BaseURL = llamaserver.DefaultBaseURL
		}
	case "omlx":
		if pc.BaseURL == "" {
			pc.BaseURL = omlx.DefaultBaseURL
		}
	case "lucebox":
		if pc.BaseURL == "" {
			pc.BaseURL = lucebox.DefaultBaseURL
		}
	case "vllm":
		if pc.BaseURL == "" {
			pc.BaseURL = vllm.DefaultBaseURL
		}
	case "rapid-mlx":
		if pc.BaseURL == "" {
			pc.BaseURL = rapidmlx.DefaultBaseURL
		}
	case "ollama":
		if pc.BaseURL == "" {
			pc.BaseURL = ollama.DefaultBaseURL
		}
	}
	if pc.BaseURL != "" && len(pc.Endpoints) == 0 && providerUsesEndpoint(pc.Type) {
		pc.Endpoints = []ProviderEndpoint{{Name: "default", BaseURL: pc.BaseURL}}
	}
	return pc
}

func inferProviderTypeFromBaseURL(baseURL string) string {
	baseURL = strings.TrimSpace(baseURL)
	if baseURL == "" {
		return ""
	}
	low := strings.ToLower(baseURL)
	switch {
	case strings.Contains(low, "openrouter.ai"):
		return "openrouter"
	case strings.Contains(low, "openai.com"):
		return "openai"
	case strings.Contains(low, "minimaxi.chat"):
		return "minimax"
	case strings.Contains(low, "dashscope.aliyuncs.com"):
		return "qwen"
	case strings.Contains(low, "z.ai"):
		return "zai"
	case strings.Contains(low, ":11434"):
		return "ollama"
	case strings.Contains(low, ":1234"):
		return "lmstudio"
	case strings.Contains(low, ":1235"):
		return "omlx"
	case strings.Contains(low, ":1236"):
		return "lucebox"
	case strings.Contains(low, ":8000"):
		return "vllm"
	default:
		return ""
	}
}

func providerUsesEndpoint(providerType string) bool {
	switch providerType {
	case "openai", "openrouter", "lmstudio", "llama-server", "omlx", "lucebox", "vllm", "rapid-mlx", "ollama", "minimax", "qwen", "zai":
		return true
	default:
		return false
	}

	}
}

