package serviceimpl

import "time"

// Clock is the API-neutral time seam used by service implementation state.
// It deliberately has no dependency on root package contract types so the
// root facade can import this package without creating a cycle.
type Clock func() time.Time

// SystemClock returns the current UTC wall-clock time.
func SystemClock() time.Time {
	return time.Now().UTC()
}

// RuntimeDeps groups constructor dependencies that are safe to pass from the
// root facade into internal implementation packages.
type RuntimeDeps struct {
	Now Clock
}

// Runtime is implementation-local service state that can be constructed from
// the root facade without depending on root public contract types.
type Runtime struct {
	deps RuntimeDeps
}

// NewRuntime constructs implementation state with defaulted dependencies.
func NewRuntime(deps RuntimeDeps) Runtime {
	return Runtime{deps: RuntimeDeps{Now: deps.Clock()}}
}

// Clock returns the configured clock or the system clock when no test seam is
// supplied.
func (d RuntimeDeps) Clock() Clock {
	if d.Now != nil {
		return d.Now
	}
	return SystemClock
}

// Now returns the runtime clock value normalized to UTC.
func (r Runtime) Now() time.Time {
	return r.deps.Clock()().UTC()
}

package serviceimpl

import (
	"encoding/json"
	"os/exec"
	"testing"
	"time"
)

func TestRuntimeDepsClockDefaultsToUTCSystemClock(t *testing.T) {
	clk := RuntimeDeps{}.Clock()
	if got := clk(); got.Location() != time.UTC {
		t.Fatalf("Clock() location = %v, want UTC", got.Location())
	}
}

func TestRuntimeDepsClockUsesInjectedClock(t *testing.T) {
	want := time.Date(2026, 5, 5, 14, 0, 0, 0, time.UTC)
	clk := RuntimeDeps{Now: func() time.Time { return want }}.Clock()
	if got := clk(); !got.Equal(want) {
		t.Fatalf("Clock() = %v, want %v", got, want)
	}
}

func TestRuntimeOwnsDefaultedClockState(t *testing.T) {
	want := time.Date(2026, 5, 5, 10, 0, 0, 0, time.FixedZone("EDT", -4*60*60))
	runtime := NewRuntime(RuntimeDeps{Now: func() time.Time { return want }})
	if got := runtime.Now(); !got.Equal(want.UTC()) || got.Location() != time.UTC {
		t.Fatalf("Now() = %v (%v), want %v UTC", got, got.Location(), want.UTC())
	}
}

func TestServiceImplDoesNotImportRootPackage(t *testing.T) {
	cmd := exec.Command("go", "list", "-json", ".")
	out, err := cmd.Output()
	if err != nil {
		t.Fatalf("go list internal/serviceimpl: %v", err)
	}

	var pkg struct {
		Imports []string
		Deps    []string
	}
	if err := json.Unmarshal(out, &pkg); err != nil {
		t.Fatalf("decode go list output: %v", err)
	}

	const root = "github.com/DocumentDrivenDX/fizeau"
	for _, imp := range pkg.Imports {
		if imp == root {
			t.Fatalf("internal/serviceimpl imports root package %q", root)
		}
	}
	for _, dep := range pkg.Deps {
		if dep == root {
			t.Fatalf("internal/serviceimpl depends on root package %q", root)
		}
	}
}

