	case ctx.Err() == context.DeadlineExceeded || (req.Timeout > 0 && time.Since(req.Started) >= req.Timeout):
		final.Status = "timed_out"
		final.Error = "wall-clock timeout"
	case ctx.Err() == context.Canceled:
		final.Status = "cancelled"
	case runErr != nil:
